def body(sub, i, tabs_html):
    d = CA if sub == "abroad/commonapp/" else UC
    facts = "".join(f'<div class="trow"><span>{f[i]}</span><b class="fv">{f[4 + i]}</b></div>' for f in d["facts"])
    steps = "".join(f"<li>{s[i]}</li>" for s in d["steps"])
    tips = "".join(f"<li>{s[i]}</li>" for s in d["tips"])
    return (f'{tabs_html}<p class="lead2">{d["intro"][i]}</p><p class="note">{H["warn"][i]}</p>'
            f'<div class="card gapp"><h3>{H["facts"][i]}</h3>{facts}</div>'
            f'<div class="card gapp"><h3>{H["steps"][i]}</h3><ol class="gsteps">{steps}</ol></div>'
            f'<div class="card gapp"><h3>{H["tips"][i]}</h3><ul>{tips}</ul>'
            f'<a class="uofficial" href="{d["url"]}" rel="noopener">{H["off"][i]}</a></div>')
